package com.bank.retirement;

import java.util.*;
import java.util.logging.*;

public class ClosestRetirementDemo {
    private static final Logger log = Logger.getLogger("Retirement");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", 34),
            new Employee("Priya", 58),   // 2 years to 60 → closest
            new Employee("Amit", 45));
        RetirementService service = new RetirementService();

        log.info(() -> "Closest to retirement: "
            + service.closestToRetirement(staff, 60).map(Employee::getName).orElse("none"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final int age;
        Employee(String name, int age) { this.name = name;
        this.age = age; }
    String getName() { return name; }
    int getAge() { return age; }
}

// ─── Would be in service/RetirementService.java ───
class RetirementService {
    Optional<Employee> closestToRetirement(List<Employee> staff, int retireAge) {
        return staff.stream()
            .min(Comparator.comparingInt((Employee e) -> retireAge - e.getAge()) // least years left
                .thenComparing(Employee::getName));                               // tie-break
    }
}
